if (costingMethod === "Weighted Average") {
  const idsToDelete = fifoRecords.filter((r) => r.id).map((r) => r.id);

  // Calculate weighted average from FIFO
  let fifoTotalQty = 0;
  let fifoTotalCost = 0;
  for (const record of fifoRecords) {
    const qty = q8(record.fifo_available_quantity);
    if (qty > 0) {
      const price = q8(record.fifo_cost_price);
      fifoTotalQty = q8(fifoTotalQty + qty);
      fifoTotalCost = q8(fifoTotalCost + qty * price);
    }
  }
  const fifoAvgCost =
    fifoTotalQty > 0 ? q8(fifoTotalCost / fifoTotalQty) : 0;

  // Merge with existing WA
  const existingWa = waRecords[0];
  const existingWaQty = q8(existingWa.wa_quantity);
  const existingWaCost = q8(existingWa.wa_cost_price);
  const newTotalQty = q8(existingWaQty + fifoTotalQty);
  const newWaCost =
    newTotalQty > 0
      ? q8(
          (existingWaCost * existingWaQty + fifoAvgCost * fifoTotalQty) /
            newTotalQty,
        )
      : existingWaCost;

  return {
    targetRecord: {
